const {missions,createState,complete}=CoreQuest;let state=createState(),sound=false,audio;const $=s=>document.querySelector(s),canvas=$('#map'),ctx=canvas.getContext('2d'),dialog=$('#quest-dialog');let activeMission=null;
function beep(f=440){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=f;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.13)}catch{}}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}
function text(t,x,y,size=12,c='#fff6d8'){ctx.fillStyle=c;ctx.font=`bold ${size}px monospace`;ctx.textAlign='center';ctx.fillText(t,x,y)}
function tree(x,y){rect(x-4,y,8,24,'#896f49');rect(x-20,y-24,40,26,'#193e38');rect(x-14,y-36,28,18,'#2c6550');rect(x-10,y-29,10,6,'#4f8260')}
function draw(){ctx.imageSmoothingEnabled=false;rect(0,0,960,576,'#376954');for(let i=0;i<140;i++){let x=(i*137+23)%960,y=(i*83+9)%576;rect(x,y,4,3,i%3?'#42745a':'#5c835d')}rect(0,260,960,68,'#b5af87');rect(446,60,68,450,'#b5af87');rect(157,180,65,250,'#b5af87');rect(738,180,65,250,'#b5af87');for(let x=0;x<960;x+=28){rect(x,263,12,3,'#cbc29b');rect(x,320,12,3,'#cbc29b')}rect(430,246,100,96,'#d0c69c');rect(451,262,57,62,'#718774');rect(461,272,37,42,'#8bb4ac');rect(471,282,17,22,'#b5d5bb');text('18A',480,299,12,'#294d42');
for(const [x,y]of [[58,69],[88,190],[320,80],[620,65],[887,60],[881,216],[70,415],[328,463],[601,500],[898,446],[89,520],[865,525]])tree(x,y);
missions.forEach((m,i)=>{const x=m.x,y=m.y,done=state.completed.includes(m.id);rect(x-75,y-39,157,105,'#244a40');rect(x-78,y-65,156,28,'#243645');rect(x-67,y-80,134,18,m.color);rect(x-67,y-53,134,98,m.color);rect(x-60,y-45,120,7,'#ffffff40');rect(x-17,y+7,34,38,'#263a3a');rect(x-12,y+12,24,33,'#416362');rect(x-51,y-22,26,24,'#314f55');rect(x+25,y-22,26,24,'#314f55');rect(x-47,y-18,8,16,'#b6d6bf');rect(x+29,y-18,8,16,'#b6d6bf');rect(x-72,y+48,144,22,'#203c36');text(m.name.toUpperCase(),x,y+63,11);rect(x-15,y-107,30,25,done?'#d8f075':'#fff2cf');text(done?'✓':String(i+1),x,y-89,17,'#263b37');if(done){rect(x+48,y-70,8,28,'#364b3e');rect(x+56,y-70,20,13,'#d8f075')}});
const {x,y}=state.player;rect(x-10,y+17,24,6,'#1d493b');rect(x-9,y-19,20,7,'#e9c064');rect(x-13,y-12,28,5,'#e9c064');rect(x-8,y-7,18,13,'#f5c9a0');rect(x+3,y-4,4,4,'#253441');rect(x-10,y+6,22,13,'#d8f075');rect(x-8,y+19,6,7,'#263547');rect(x+6,y+19,6,7,'#263547');text('YOU',x,y-26,9,'#eaf5c9');}
function render(){ $('#progress').textContent=`QUESTS ${state.completed.length} / 6`;$('#score').textContent=`XP ${String(state.score).padStart(3,'0')}`;$('#missions').innerHTML=missions.map((m,i)=>`<button class="mission ${state.completed.includes(m.id)?'done':''}" data-mission="${m.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><span><strong>${m.name}</strong><small>${m.person}</small></span><span>${state.completed.includes(m.id)?'✓':'↗'}</span></button>`).join('');$('#match').disabled=state.completed.length!==6;$('#match').textContent=state.completed.length===6?'★ QUEST COMPLETE — FIND MY FIT':'FINISH 6 QUESTS TO FIND YOUR FIT';draw()}
function start(){state.started=true;$('#intro').hidden=true;beep(660);canvas.focus();render()}
function show(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal()}
function mission(id){if(!state.started)start();const m=missions.find(m=>m.id===id);activeMission=id;state.player={x:m.x,y:m.y+(m.y<260?95:-125)};draw();beep();show(`<p class="eyebrow">QUEST ${missions.indexOf(m)+1} / 6 · ${m.person.toUpperCase()}</p><h2 id="dialog-title">${m.question}</h2><p>${m.story}</p><p><b>Which is the best starting point for this brief?</b></p><div class="answers"><button data-answer="core">A / INTEL CORE SERIES 3<small>Everyday essentials, focused on value</small></button><button data-answer="ultra">B / INTEL CORE ULTRA SERIES 3<small>More headroom for demanding work</small></button><button data-answer="both">C / BOTH FAMILIES<small>A shared feature or capability</small></button></div><div class="feedback" id="feedback" aria-live="polite" hidden></div><button class="primary" id="continue" hidden>BACK TO TOWN →</button>`)}
function answer(value){const m=missions.find(m=>m.id===activeMission);const result=complete(state,m.id,value);$('#feedback').hidden=false;$('#feedback').innerHTML=`<strong>${result.correct?'✦ Great match!':'✦ Discovery unlocked!' } ${result.first?(result.correct?'+100 XP':'+50 learning XP'):'Already explored'}</strong><p>${m.why}</p><p>XP rewards learning. It is not a processor performance score.</p>`;document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);$('#continue').hidden=false;$('#continue').textContent=result.finished?'★ FINISH QUEST →':'BACK TO TOWN →';$('#continue').focus();beep(result.correct?880:330);render();$('#announcement').textContent=result.finished?'All six quests complete! Your personal match is unlocked.':`${m.name} complete. ${6-state.completed.length} quests to explore.`}
function personal(){activeMission=null;show(`<p class="eyebrow">QUEST COMPLETE · ${state.score} LEARNING XP</p><h2 id="dialog-title">Now, choose your own adventure.</h2><p>Your quiz score doesn’t choose your chip. Your real routine does. What sounds most like your day?</p><div class="answers"><button data-fit="core">☀ CLASSES, CALLS, DOCUMENTS & STREAMING<small>I want everyday essentials and good value.</small></button><button data-fit="ultra">✦ EDITING, GAMING & DEMANDING LOCAL AI<small>I regularly need more creative or graphics headroom.</small></button><button data-fit="mixed">↔ A BIT OF BOTH<small>My workload changes from day to day.</small></button></div>`)}
function fit(kind){const info={core:['EVERYDAY EXPLORER','Intel Core Series 3','Start here for price-conscious everyday productivity, studying, calls and entertainment. Modern essentials can be exactly the right fit.'],ultra:['BIG-IDEA ADVENTURER','Intel Core Ultra Series 3','Explore this family for regular demanding creation, gaming or supported local AI. Check the specific graphics configuration and app requirements.'],mixed:['VERSATILE VOYAGER','Let your busiest days decide','Mostly everyday tasks with occasional light editing? Start with Core Series 3. Regularly tackling demanding projects or games? Explore Core Ultra Series 3.']}[kind];show(`<p class="eyebrow">YOUR ADVENTURER PROFILE</p><div class="result-badge">✦</div><h2 id="dialog-title">${info[0]}</h2><p><b>${info[1]}</b></p><p>${info[2]}</p><div class="feedback">Both can be the right choice. Compare the actual laptop’s RAM, screen, battery tests, software compatibility and full price before buying.</div><button class="primary" id="share">COPY MY QUEST RESULT ↗</button><p id="share-status" role="status"></p><button id="choose-again">CHOOSE AGAIN</button>`);$('#share').onclick=async()=>{try{await navigator.clipboard.writeText(`Core Quest: ${info[0]} — ${info[1]}. Find your fit: ${location.href.split('#')[0]}`);$('#share-status').textContent='Copied! Share your adventure.'}catch{$('#share-status').textContent='Copy this page’s address to share Core Quest.'}}}
function guide(){activeMission=null;show(`<p class="eyebrow">FIELD GUIDE / NO TECH DICTIONARY NEEDED</p><h2 id="dialog-title">Know your sidekicks.</h2><div class="guide-grid"><div><h3>Core Ultra Series 3</h3><p>Panther Lake. More headroom for demanding creation, gaming and supported on-device AI.</p><p>Up to 16 CPU cores, 12 Xe graphics cores and 50 NPU TOPS.</p></div><div><h3>Core Series 3</h3><p>Wildcat Lake. Modern everyday computing and right-sized AI for price-sensitive laptops.</p><p>Up to 6 CPU cores, 2 Xe graphics cores and 17 NPU TOPS.</p></div></div><div class="feedback"><b>Shared foundation: Intel 18A</b><br>Both include integrated graphics and a dedicated AI engine. The CPU handles general tasks, the GPU handles visuals and the NPU accelerates supported AI work.</div><p class="footnote">Family maximums, not every model. TOPS means trillions of operations per second; it is not an app-speed guarantee. Core’s up to 40 platform TOPS combines multiple engines and is not comparable to NPU-only TOPS. Performance and battery life depend on the laptop and workload. Source links are below the game.</p>`)}
function move(dx,dy){if(!state.started||dialog.open)return;state.player.x=Math.max(20,Math.min(940,state.player.x+dx*18));state.player.y=Math.max(35,Math.min(535,state.player.y+dy*18));draw()}
function interact(){if(!state.started){start();return}const nearest=missions.map(m=>({m,d:Math.hypot(m.x-state.player.x,m.y-state.player.y)})).sort((a,b)=>a.d-b.d)[0];if(nearest.d<155)mission(nearest.m.id);else $('#announcement').textContent='Walk closer to a numbered building, or tap a quest in the log.'}
$('#start').onclick=start;$('#missions').onclick=e=>{const b=e.target.closest('[data-mission]');if(b)mission(b.dataset.mission)};$('#close-dialog').onclick=()=>dialog.close();$('#guide-button').onclick=guide;$('#match').onclick=personal;$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',sound);$('#sound').textContent=sound?'♪ SOUND ON':'♪ SOUND OFF';beep()};$('#restart').onclick=()=>{state=createState();activeMission=null;$('#intro').hidden=false;$('#announcement').textContent='A fresh adventure awaits. Six neighbours, two great sidekicks.';render();$('#start').focus()};$('#interact').onclick=interact;
$('#dialog-content').onclick=e=>{const a=e.target.closest('[data-answer]'),f=e.target.closest('[data-fit]');if(a)answer(a.dataset.answer);if(f)fit(f.dataset.fit);if(e.target.closest('#continue')){if(state.completed.length===6)personal();else dialog.close()}if(e.target.closest('#choose-again'))personal()};document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(...b.dataset.move.split(',').map(Number)));
canvas.addEventListener('keydown',e=>{const keys={ArrowUp:[0,-1],w:[0,-1],ArrowDown:[0,1],s:[0,1],ArrowLeft:[-1,0],a:[-1,0],ArrowRight:[1,0],d:[1,0]};const k=keys[e.key]||keys[e.key.toLowerCase()];if(k){e.preventDefault();move(...k)}if(e.key==='Enter'||e.key===' '){e.preventDefault();interact()}});
canvas.addEventListener('click',e=>{if(!state.started)return;canvas.focus();const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*960/r.width,y=(e.clientY-r.top)*576/r.height;const m=missions.find(m=>Math.abs(m.x-x)<85&&y>m.y-115&&y<m.y+76);if(m)mission(m.id);else{state.player={x:Math.max(20,Math.min(940,x)),y:Math.max(35,Math.min(535,y))};draw()}});render();
